/* From Uiverse.io by Daniel1227k - Tags: gradient, card */
.__UIV_SCOPE__ .card {
  position: relative;
  width: 190px;
  height: 254px;
  background: #f00;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(315deg,#03a9f4,#ff0058);
}

.__UIV_SCOPE__ .card::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(315deg,#03a9f4,#ff0058);
  filter: blur(30px);
}

.__UIV_SCOPE__ .card b {
  position: absolute;
  inset: 6px;
  background: rgba(0, 0, 0, 0.6);
  z-index: 2;
}

.__UIV_SCOPE__ .card img {
  position: absolute;
  z-index: 3;
  scale: 0.8;
  opacity: 0.25;
  transition: 0.5s;
}

.__UIV_SCOPE__ .card:hover img {
  scale: 0.5;
  opacity: 0.9;
  transform: translateY(-70px);
}

.__UIV_SCOPE__ .card .content {
  position: absolute;
  z-index: 3;
  bottom: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  transform: scale(0);
  transition: 0.5s;
}

.__UIV_SCOPE__ .card:hover .content {
  transform: scale(1);
  bottom: 25px;
}

.__UIV_SCOPE__ .content .title {
  position: relative;
  color: #fff;
  font-weight: 500;
  line-height: 1em;
  font-size: 1em;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-align: center;
}

.__UIV_SCOPE__ .content .title span {
  font-weight: 300;
  font-size: 0.70em;
}

.__UIV_SCOPE__ .content .sci {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  margin-top: 5px;
}

.__UIV_SCOPE__ .sci li {
  list-style: none;
}

.__UIV_SCOPE__ .sci li .fa-brands {
  width: 14px;
}

.__UIV_SCOPE__ .sci li .fa-facebook {
  width: 10px;
}

.__UIV_SCOPE__ .sci li a {
  position: relative;
  text-decoration: none;
  color: rgba(255, 255, 255, 0.5);
  background: rgba(0, 0, 0, 0.2);
  fill: currentColor;
  width: 30px;
  height: 30px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 4px;
  transition: 0.5s;
}

.__UIV_SCOPE__ .sci li a:hover {
  fill: currentColor;
  color: rgba(255, 255, 255, 1);
}
